import { ExerciseRecord } from '../types/studio';

function ex(
  csvId: number,
  name: string,
  muscleGroup: string,
  equipment: string,
  instructions: string
): Omit<ExerciseRecord, 'userId'> {
  return {
    id: `ex_csv_${csvId}`,
    name,
    muscleGroup,
    equipment,
    instructions,
    custom: false,
  };
}

